const $=s=>document.querySelector(s);
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2});
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const savedCart=readStorage('pokepaka-demo-cart',{});
const state={products:[],category:'Wszystkie',type:'',query:'',limit:8,sort:'default',favorites:new Set(readStorage('pokepaka-favorites',[]).filter?.(x=>Number.isInteger(x))??[]),cart: savedCart&&typeof savedCart==='object'&&!Array.isArray(savedCart)?savedCart:{}};
let toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function persist(){try{localStorage.setItem('pokepaka-demo-cart',JSON.stringify(state.cart));localStorage.setItem('pokepaka-favorites',JSON.stringify([...state.favorites]))}catch{}updateCounts()}
function updateCounts(){$('#cart-count').textContent=Object.values(state.cart).reduce((a,b)=>a+Number(b),0);$('#favorite-count').textContent=state.favorites.size;$('#favorite-count').hidden=!state.favorites.size}
function render(){let products=state.products.filter(p=>(state.category==='Wszystkie'||state.category==='Ulubione'&&state.favorites.has(p.id)||p.category===state.category)&&(!state.type||state.type===p.type)&&(!state.query||`${p.name} ${p.category} ${p.type} ${p.language}`.toLocaleLowerCase('pl').includes(state.query.toLocaleLowerCase('pl'))));
if(state.sort==='price-asc')products.sort((a,b)=>a.price-b.price);if(state.sort==='price-desc')products.sort((a,b)=>b.price-a.price);if(state.sort==='name')products.sort((a,b)=>a.name.localeCompare(b.name,'pl'));
$('#result-count').textContent=`${products.length} ${products.length===1?'produkt':products.length>1&&products.length<5?'produkty':'produktów'}`;
document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===state.category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
$('#active-filter').hidden=!state.type&&!state.query;$('#active-filter>span').textContent=[state.type,state.query?`Wyniki dla: „${state.query}”`:''].filter(Boolean).join(' · ');
$('#product-grid').innerHTML=products.length?products.slice(0,state.limit).map(p=>`<article class="product-card"><div style="position:relative"><button class="product-photo" data-detail="${p.id}" aria-label="Zobacz ${esc(p.name)}"><span class="product-badge ${p.id===1?'special':''}">${p.id===1?'KOLEKCJA':esc(p.category.toUpperCase())}</span><span class="language-badge ${p.language==='Angielski'?'english':''}">${esc(p.language.toUpperCase())}</span><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" width="250" height="250"></button><button class="product-favorite ${state.favorites.has(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="${state.favorites.has(p.id)?'Usuń z ulubionych':'Dodaj do ulubionych'}: ${esc(p.name)}" aria-pressed="${state.favorites.has(p.id)}">${icon('heart')}</button></div><div class="product-body"><div class="product-meta">${esc(p.type)}<i></i>${esc(p.language)}</div><button class="product-name" data-detail="${p.id}">${esc(p.name)}</button><div class="product-bottom"><span class="price">${money(p.price)} <small>zł</small></span><button class="product-add" data-add="${p.id}" aria-label="Dodaj do koszyka: ${esc(p.name)}">${icon('bag')}<span>Do koszyka</span></button></div></div></article>`).join(''):`<div class="empty-state">${icon(state.category==='Ulubione'?'heart':'search')}<h3>${state.category==='Ulubione'?'Tu zamieszkają Twoje perełki.':'Jeszcze nie ten pull.'}</h3><p>${state.category==='Ulubione'?'Kliknij serduszko przy produkcie, aby zachować go na później.':'Nie znaleźliśmy produktów. Spróbuj innej nazwy lub zmień filtry.'}</p><button class="button button-outline" data-reset>Pokaż wszystkie produkty ${icon('arrow')}</button></div>`;
$('#load-more').hidden=products.length<=state.limit;updateCounts()}
function selectCategory(category,type=''){state.category=category;state.type=type;state.query='';state.limit=8;$('#search').value='';render();$('#menu-dialog').close();$('#catalog').scrollIntoView({behavior:'smooth'})}
function add(id){if(!state.products.some(p=>p.id===id))return;const count=Number(state.cart[id]||0);if(count>=99){notify('Maksymalna liczba sztuk w podglądzie to 99.');return}state.cart[id]=count+1;persist();notify('Dodano do koszyka pokazowego ✓');if($('#cart-dialog').open)renderCart()}
function detail(id){const p=state.products.find(p=>p.id===id);if(!p)return;$('#product-detail').innerHTML=`<div class="detail-image"><img src="${esc(p.image)}" alt="${esc(p.name)}"></div><div class="detail-copy"><span class="eyebrow">${esc(p.category)} / ${esc(p.type)}</span><h2 id="detail-title">${esc(p.name)}</h2><div class="detail-specs"><span>Język: ${esc(p.language)}</span><span>PLN / brutto</span></div><span class="price">${money(p.price)} <small>zł</small></span><button class="button button-red" data-add="${p.id}">Dodaj do koszyka ${icon('bag')}</button><p class="detail-demo">Produkt z katalogu PokePaka. Koszyk działa w trybie pokazowym. Cenę i aktualną dostępność sprawdzisz w obecnym sklepie.</p><a class="source-link" href="${esc(p.url)}" target="_blank" rel="noopener">Zobacz produkt w obecnym sklepie ↗</a></div>`;$('#product-dialog').showModal()}
function renderCart(){const entries=Object.entries(state.cart).map(([id,quantity])=>({p:state.products.find(p=>p.id===Number(id)),quantity:Number(quantity)})).filter(e=>e.p&&e.quantity>0);if(!entries.length){$('#cart-items').innerHTML=`<div class="cart-empty">${icon('bag')}<h3>Kolekcja czeka na nowości.</h3><p>Wybierz coś dla siebie.<br>Twój kolejny ulubiony zestaw może być tuż obok.</p><button class="button button-dark" data-continue>Odkrywaj produkty ${icon('arrow')}</button></div>`;$('#cart-summary').innerHTML='';return}
$('#cart-items').innerHTML=entries.map(({p,quantity})=>`<div class="cart-item"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div class="cart-item-info"><h3>${esc(p.name)}</h3><span class="cart-item-price">${money(p.price*quantity)} zł</span><div class="cart-quantity"><div class="quantity-control"><button data-quantity="${p.id}" data-delta="-1" aria-label="Zmniejsz liczbę: ${esc(p.name)}">−</button><span aria-label="Liczba sztuk">${quantity}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Zwiększ liczbę: ${esc(p.name)}">+</button></div><button class="cart-remove" data-remove="${p.id}" aria-label="Usuń z koszyka: ${esc(p.name)}">Usuń</button></div></div></div>`).join('');const total=entries.reduce((sum,{p,quantity})=>sum+p.price*quantity,0);$('#cart-summary').innerHTML=`<div class="cart-total"><span>Wartość produktów</span><strong>${money(total)} zł</strong></div><p class="cart-tax-note">Cena pokazowa brutto. Koszt dostawy zostanie ustalony po podłączeniu sklepu.</p><button class="button button-dark" style="width:100%" data-checkout>Sprawdź podsumowanie ${icon('arrow')}</button><button class="button button-outline cart-continue" data-continue>Kontynuuj przeglądanie</button><div class="checkout-info" id="checkout-info" hidden></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('[data-category]'))selectCategory(b.dataset.category);if(b.matches('[data-type]'))selectCategory('Wszystkie',b.dataset.type);if(b.matches('[data-filter]')){state.category=b.dataset.filter;state.limit=8;render()}if(b.matches('[data-add]'))add(Number(b.dataset.add));if(b.matches('[data-detail]'))detail(Number(b.dataset.detail));if(b.matches('[data-favorite]')){const id=Number(b.dataset.favorite);if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);persist();render()}if(b.matches('.dialog-close'))b.closest('dialog').close();if(b.matches('[data-continue]')){$('#cart-dialog').close();$('#catalog').scrollIntoView({behavior:'smooth'})}if(b.matches('[data-remove]')){delete state.cart[b.dataset.remove];persist();renderCart()}if(b.matches('[data-quantity]')){const id=b.dataset.quantity;const quantity=Number(state.cart[id]||0)+Number(b.dataset.delta);if(quantity<=0)delete state.cart[id];else state.cart[id]=Math.min(quantity,99);persist();renderCart()}if(b.matches('[data-checkout]')){$('#checkout-info').hidden=false;$('#checkout-info').textContent='To podsumowanie pokazowe. Zamówienie nie zostało złożone. Po podłączeniu płatności, dostaw i stanów magazynowych pojawi się tutaj właściwa finalizacja zakupu.'}if(b.matches('[data-reset]'))selectCategory('Wszystkie')});
$('.cart-button').addEventListener('click',()=>{renderCart();$('#cart-dialog').showModal()});$('.favorites-button').addEventListener('click',()=>selectCategory('Ulubione'));$('.mobile-menu').addEventListener('click',()=>$('#menu-dialog').showModal());$('#menu-dialog>a').addEventListener('click',()=>$('#menu-dialog').close());$('.faq-link').addEventListener('click',e=>{e.preventDefault();$('.faq-section').scrollIntoView({behavior:'smooth'})});$('.search').addEventListener('submit',e=>{e.preventDefault();state.query=$('#search').value.trim();state.category='Wszystkie';state.type='';state.limit=8;render();$('#catalog').scrollIntoView({behavior:'smooth'});$('#search').blur()});$('#search').addEventListener('input',e=>{state.query=e.target.value.trim();state.category='Wszystkie';state.type='';state.limit=8;render()});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render()});$('#load-more').addEventListener('click',()=>{state.limit+=8;render()});$('#active-filter>button').addEventListener('click',()=>{state.type='';state.query='';$('#search').value='';render()});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}}));
fetch('products.json').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json()}).then(products=>{state.products=products;state.cart=Object.fromEntries(Object.entries(state.cart).filter(([id,q])=>products.some(p=>p.id===Number(id))&&Number.isInteger(q)&&q>0&&q<=99));render()}).catch(()=>{$('#product-grid').innerHTML='<div class="empty-state"><h3>Nie udało się wczytać produktów.</h3><p>Odśwież stronę, aby spróbować ponownie.</p></div>';$('#load-more').hidden=true});
